    decoded = JSON.parse(json);
  } catch {
    throw new Error('Unknown cursor');
  }
  if (
    !decoded ||
    typeof decoded !== 'object' ||
    typeof decoded.o !== 'number' ||
    !Number.isInteger(decoded.o) ||
    decoded.o < 0 ||
    decoded.o > TOTAL
  ) {
    throw new Error('Unknown cursor');
  }
  return decoded.o;
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description:
        'List events in source order with cursor-based pagination. ' +
        `page_size must be between ${MIN_PAGE_SIZE} and ${MAX_PAGE_SIZE}.`,
      inputSchema: {
        type: 'object',
        properties: {
          cursor: {
            type: 'string',
            description: 'Opaque pagination cursor returned by a previous call.'
          },
          page_size: {
            type: 'integer',
            minimum: MIN_PAGE_SIZE,
            maximum: MAX_PAGE_SIZE,
            default: DEFAULT_PAGE_SIZE,
            description: `Number of events per page (${MIN_PAGE_SIZE}-${MAX_PAGE_SIZE}).`
