{"path":"verify.mjs","content":"import { listTools, callTool } from './server.mjs';

function assert(cond, msg) {
  if (!cond) {
    console.error('FAIL:', msg);
    process.exit(1);
  }
  console.log('OK:  ', msg);
}

// 1. listTools returns events_list with proper schema
const tools = await listTools();
assert(tools.length === 1, 'listTools returns exactly one tool');
assert(tools[0].name === 'events_list', 'tool name is events_list');
assert(tools[0].inputSchema.additionalProperties === false, 'additionalProperties is false');
assert(tools[0].inputSchema.type === 'object', 'inputSchema type is object');
assert('cursor' in tools[0].inputSchema.properties, 'cursor property exists');
assert('page_size' in tools[0].inputSchema.properties, 'page_size property exists');
assert(tools[0].inputSchema.properties.page_size.minimum === 1, 'page_size minimum is 1');
assert(tools[0].inputSchema.properties.page_size.maximum === 3, 'page_size maximum is 3');

// 2. First page returns e1, e2 + cursor
const r1 = await callTool('events_list', {});
const text1 = r1.content[0].text;
const parsed1 = JSON.parse(text1);
assert(parsed1.events.length === 2, 'first page has 2 events');
assert(parsed1.events[0].id === 'e1', 'first page starts with e1');
assert(parsed1.events[1].id === 'e2', 'first page second is e2');
assert(typeof parsed1.next_cursor === 'string', 'first page has next_cursor');

// 3. Second page follows cursor in source order
const r2 = await callTool('events_list', { cursor: parsed1.next_cursor });
const parsed2 = JSON.parse(r2.content[0].text);
assert(parsed2.events[0].id === 'e3', 'second page starts with e3');
assert(parsed2.events[1].id === 'e4', 'second page second is e4');
assert(parsed2.next_cursor === undefined, 'last page has no next_cursor');

// 4. page_size honored
const r3 = await callTool('events_list', { page_size: 3 });
const parsed3 = JSON.parse(r3.content[0].text);
assert(parsed3.events.length === 3, 'page_size=3 returns 3 events');
assert(parsed3.events[0].id === 'e1' && parsed3.events[2].id === 'e3', 'page_size=3 returns e1,e2,e3');

const r4 = await callTool('events_list', { page_size: 1 });
const parsed4 = JSON.parse(r4.content[0].text);
assert(parsed4.events.length === 1, 'page_size=1 returns 1 event');
assert(parsed4.events[0].id === 'e1', 'page_size=1 returns e1');

// 5. Reject invalid page_size
for (const bad of [0, 4, -1, 2.5, '2', null, true, [], {}]) {
  let threw = false;
  try { await callTool('events_list', { page_size: bad }); } catch { threw = true; }
  assert(threw, `invalid page_size rejected: ${JSON.stringify(bad)}`);
}

// 6. Reject unknown cursor
for (const bad of ['not-a-cursor', '', 'AAAA', Buffer.from('not json').toString('base64'),
                   Buffer.from('{"o":-1}').toString('base64'),
                   Buffer.from('{"o":99}').toString('base64'),
                   Buffer.from('{"o":"x"}').toString('base64'),
                   Buffer.from('[]').toString('base64')]) {
  let threw = false;
  try { await callTool('events_list', { cursor: bad }); } catch { threw = true; }
  assert(threw, `unknown cursor rejected: ${JSON.stringify(bad)}`);
}

// 7. Reject non-string cursor
let threw = false;
try { await callTool('events_list', { cursor: 5 }); } catch { threw = true; }
assert(threw, 'numeric cursor rejected');

// 8. Reject extra fields
for (const extra of ['foo', 'cursor2', '']) {
  let t = false;
  try { await callTool('events_list', { page_size: 2, [extra]: 'x' }); } catch { t = true; }
  assert(t, `extra field "${extra}" rejected`);
}

// 9. Reject unknown tool
threw = false;
try { await callTool('nope', {}); } catch { threw = true; }
assert(threw, 'unknown tool rejected');

threw = false;
try { await callTool('events_list_2', {}); } catch { threw = true; }
assert(threw, 'similar unknown tool rejected');

// 10. Cursor opacity: must not directly leak offset
const c = parsed1.next_cursor;
const dec = Buffer.from(c, 'base64').toString('utf-8');
assert(!/["':]0\b/.test(c) && c !== '2', 'cursor is opaque (not raw offset)');

// 11. Round-trip: walking all pages with various page_sizes yields every event exactly once
const collected = [];
let cursor;
let safety = 10;
while (safety-- > 0) {
  const args = {};
  if (cursor) args.cursor = cursor;
  const r = await callTool('events_list', { ...args, page_size: 2 });
  const p = JSON.parse(r.content[0].text);
  collected.push(...p.events.map(e => e.id));
  cursor = p.next_cursor;
  if (!cursor) break;
}
assert(JSON.stringify(collected) === JSON.stringify(['e1', 'e2', 'e3', 'e4']), 'walk yields all events in order');

console.log('\nAll verification checks passed.');"}

